// ============================================
// FORMAT LLM SUCCESS RESPONSE
// ============================================

const input = $input.first().json;
const validationData = $('Detect Intent').first().json;

const tokensUsed = input.tokens_used || 0;
const intent = input.intent || 'question';

const COSTS = {
  recette: { base: 3, rate: 1.0, max: 10 },
  question: { base: 1, rate: 0.5, max: 5 },
  default: { base: 1, rate: 0.5, max: 5 }
};

const cost = COSTS[intent] || COSTS.default;
const creditsConsumed = Math.min(cost.base + (tokensUsed / 1000) * cost.rate, cost.max);

return {
  success: true,
  response: input.response,
  intent: intent,
  confidence: input.confidence || 0.9,
  tokens_used: tokensUsed,
  credits_consumed: Math.ceil(creditsConsumed),
  project_id: validationData.project_id,
  user_id: validationData.data?.user_id,
  guild_id: validationData.data?.guild_id,
  request_content: validationData.data?.content || ''
};

// ============================================
// FORMAT ERROR / FALLBACK
// ============================================

const input = $input.first().json;
const validationData = $('Detect Intent').first().json;

let response = "Je n'ai pas bien compris. Peux-tu reformuler ?";
let intent = 'unknown';

if (input.intent === 'out_of_scope') {
  response = "Je suis spécialisé en cuisine ! Cette question est hors de mon domaine.";
  intent = 'out_of_scope';
}

return {
  success: true,
  response: response,
  intent: intent,
  confidence: 0.5,
  tokens_used: 0,
  credits_consumed: 0,
  project_id: validationData.project_id,
  user_id: validationData.data?.user_id,
  guild_id: validationData.data?.guild_id,
  request_content: validationData.data?.content || ''
};
